function stringifyBonus (bonus, includeMetadata = false) { let textdata = ''; if (includeMetadata) { textdata += `${bonus.set.name} Packet ${bonus.packet.number}
`; textdata += `Question ID: ${bonus._id}
`; } textdata += `${bonus.number}. ${bonus.leadin_sanitized}
`; for (let i = 0; i < bonus.parts.length; i++) { textdata += `${getBonusPartLabel(bonus, i)} ${bonus.parts_sanitized[i]}
`; textdata += `ANSWER: ${bonus.answers_sanitized[i]}
`; } textdata += `<${bonus.category} / ${bonus.subcategory}${bonus.alternate_subcategory ? ' / ' + bonus.alternate_subcategory : ''}>
`; return textdata; }

